CREATE TABLE sku_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by text NOT NULL, txn_date date NOT NULL DEFAULT current_date, sku_id uuid NOT NULL REFERENCES skus(id) ON DELETE CASCADE, txn_type text NOT NULL, qty_in numeric(12,2) NOT NULL DEFAULT 0, qty_out numeric(12,2) NOT NULL DEFAULT 0, unit_cost numeric(12,2) NOT NULL DEFAULT 0, order_id uuid REFERENCES business_orders(id) ON DELETE CASCADE, reference text, source text, notes text, created_at timestamptz NOT NULL DEFAULT now())